<script setup>import { computed, onMounted, ref } from "vue"; import AdminLayout from "../../layouts/AdminLayout.vue"; import StatusBadge from "../../components/StatusBadge.vue"; import { materialService, requestService, userService } from "../../services/api"; const items = ref([]), users = ref([]), materials = ref([]), error = ref(""), toast = ref(""); const userById = computed(() => Object.fromEntries(users.value.map((user) => [user.id, user]))); const materialById = computed(() => Object.fromEntries(materials.value.map((item) => [item.id, item]))); const load = async () => { try { const [requests, allUsers, allMaterials] = await Promise.all([requestService.all(), userService.list(), materialService.list()]); items.value = requests.data; users.value = allUsers.data; materials.value = allMaterials.data; } catch (exception) { error.value = exception.message; } }; const approve = async (item) => { try { await requestService.approve(item.id); toast.value = "Demande approuvée."; await load(); } catch (exception) { error.value = exception.message; } }; const reject = async (item) => { const motif_refus = prompt("Motif du refus :"); if (!motif_refus?.trim()) return; try { await requestService.reject(item.id, { motif_refus }); toast.value = "Demande refusée."; await load(); } catch (exception) { error.value = exception.message; } }; const returnMaterial = async (item) => { if (!confirm("Confirmer la restitution de ce matériel ?")) return; try { await requestService.returnMaterial(item.id); toast.value = "Restitution enregistrée."; await load(); } catch (exception) { error.value = exception.message; } }; const pending = computed(() => items.value.filter((item) => item.statut === "en_attente")); const approved = computed(() => items.value.filter((item) => item.statut === "approuve")); onMounted(load);</script><template><AdminLayout><section class="p-5 md:p-10"><h1 class="text-3xl font-bold">Demandes</h1><p class="mt-2 text-slate-500">Validez les demandes puis enregistrez les restitutions.</p><div v-if="error" class="alert alert-error mt-6">{{ error }}</div><template v-else><h2 class="mt-8 text-lg font-bold">Demandes en attente</h2><div class="mt-3 overflow-x-auto rounded-2xl bg-white shadow-sm"><table class="table"><thead><tr><th>Utilisateur</th><th>Matériel</th><th>Qté</th><th>Type</th><th>Retour</th><th>Motif</th><th></th></tr></thead><tbody><tr v-for="item in pending" :key="item.id"><td><RouterLink :to="`/admin/utilisateurs?user=${item.utilisateur_id}`" class="font-medium text-[#17482d] hover:underline">{{ userById[item.utilisateur_id]?.nom_complet || 'Utilisateur introuvable' }}</RouterLink><p class="text-xs text-slate-400">{{ userById[item.utilisateur_id]?.email }}</p></td><td>{{ materialById[item.materiel_id]?.nom || `Matériel #${item.materiel_id}` }}</td><td>{{ item.quantite }}</td><td class="capitalize">{{ item.type_emprunt }}</td><td>{{ item.date_fin_prevue || '—' }}</td><td class="max-w-48 truncate">{{ item.motif }}</td><td class="flex gap-2"><button class="btn btn-success btn-xs" @click="approve(item)">Approuver</button><button class="btn btn-error btn-xs" @click="reject(item)">Refuser</button></td></tr><tr v-if="!pending.length"><td colspan="7" class="py-8 text-center text-slate-500">Aucune demande en attente.</td></tr></tbody></table></div><h2 class="mt-10 text-lg font-bold">Matériels empruntés</h2><div class="mt-3 overflow-x-auto rounded-2xl bg-white shadow-sm"><table class="table"><thead><tr><th>Utilisateur</th><th>Matériel</th><th>Qté</th><th>Statut</th><th></th></tr></thead><tbody><tr v-for="item in approved" :key="item.id"><td><RouterLink :to="`/admin/utilisateurs?user=${item.utilisateur_id}`" class="font-medium text-[#17482d] hover:underline">{{ userById[item.utilisateur_id]?.nom_complet || 'Utilisateur introuvable' }}</RouterLink></td><td>{{ materialById[item.materiel_id]?.nom || `Matériel #${item.materiel_id}` }}</td><td>{{ item.quantite }}</td><td><StatusBadge :status="item.statut" /></td><td><button class="btn btn-outline btn-xs" @click="returnMaterial(item)">Enregistrer la restitution</button></td></tr><tr v-if="!approved.length"><td colspan="5" class="py-8 text-center text-slate-500">Aucun matériel actuellement emprunté.</td></tr></tbody></table></div></template><div v-if="toast" class="toast toast-end"><div class="alert alert-success">{{ toast }}</div></div></section></AdminLayout></template>
